def is_palindrome_sentence(text):
    cleaned = ""
    for char in text:
        if char.isalpha():
            cleaned += char.lower()
    return cleaned == cleaned[::-1]

print(is_palindrome_sentence("A man a plan a canal Panama"))
print(is_palindrome_sentence("racecar"))
print(is_palindrome_sentence("hello world"))

